// Build step: bundle the CommonJS backend modules in src/ into a single browser
// script (public/pamra-backend.js) so the prototype runs fully client-side on a
// static host (Vercel). src/ stays the single source of truth — `node server.js`
// still works for local development; this only produces the browser build.
//
// Run: node build-bundle.js   (also wired as `npm run build`)

const fs = require('fs');
const path = require('path');

const ROOT = __dirname;

// Order doesn't matter (modules load lazily on first require), but list every
// file the runtime reaches transitively.
const FILES = [
  'src/auth.js',
  'src/data/markets.js',
  'src/data/staff.js',
  'src/data/amisData.js',
  'src/data/mcmisData.js',
  'src/data/newsData.js',
  'src/data/simulator.js',
  'src/data/gateSimulator.js',
  'src/engine/crossSourceValidator.js',
  'src/engine/statisticalAnomaly.js',
  'src/engine/geoStaffVerifier.js',
  'src/engine/fraudScorer.js',
  'src/engine/authenticityEngine.js',
  'src/engine/integrityLedger.js'
];

const idOf = (f) => f.replace(/\\/g, '/').replace(/\.js$/, '');

// ── Module loader + crypto shim (browser side) ──────────────────────────────
const PRELUDE = `// AUTO-GENERATED by build-bundle.js — do not edit. Source of truth is src/.
(function () {
  'use strict';

  // ── Synchronous SHA-256 (UTF-8) so the integrity ledger hashes work in-browser ──
  function sha256bytes(bytes) {
    function rrot(x, n) { return (x >>> n) | (x << (32 - n)); }
    var H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
    var K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
      0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
      0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
      0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
      0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
      0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
      0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
      0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
    var l = bytes.length;
    var k = (56 - ((l + 1) % 64) + 64) % 64;
    var total = l + 1 + k + 8;
    var m = new Uint8Array(total);
    m.set(bytes, 0);
    m[l] = 0x80;
    var hi = Math.floor(l / 0x20000000);
    var lo = (l * 8) >>> 0;
    m[total-8]=(hi>>>24)&0xff; m[total-7]=(hi>>>16)&0xff; m[total-6]=(hi>>>8)&0xff; m[total-5]=hi&0xff;
    m[total-4]=(lo>>>24)&0xff; m[total-3]=(lo>>>16)&0xff; m[total-2]=(lo>>>8)&0xff; m[total-1]=lo&0xff;
    var w = new Array(64);
    for (var off = 0; off < total; off += 64) {
      for (var i = 0; i < 16; i++) w[i] = (m[off+i*4]<<24)|(m[off+i*4+1]<<16)|(m[off+i*4+2]<<8)|(m[off+i*4+3]);
      for (var i = 16; i < 64; i++) {
        var s0 = rrot(w[i-15],7)^rrot(w[i-15],18)^(w[i-15]>>>3);
        var s1 = rrot(w[i-2],17)^rrot(w[i-2],19)^(w[i-2]>>>10);
        w[i] = (w[i-16]+s0+w[i-7]+s1)|0;
      }
      var a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
      for (var i = 0; i < 64; i++) {
        var S1=rrot(e,6)^rrot(e,11)^rrot(e,25);
        var ch=(e&f)^((~e)&g);
        var t1=(h+S1+ch+K[i]+w[i])|0;
        var S0=rrot(a,2)^rrot(a,13)^rrot(a,22);
        var maj=(a&b)^(a&c)^(b&c);
        var t2=(S0+maj)|0;
        h=g; g=f; f=e; e=(d+t1)|0; d=c; c=b; b=a; a=(t1+t2)|0;
      }
      H[0]=(H[0]+a)|0;H[1]=(H[1]+b)|0;H[2]=(H[2]+c)|0;H[3]=(H[3]+d)|0;
      H[4]=(H[4]+e)|0;H[5]=(H[5]+f)|0;H[6]=(H[6]+g)|0;H[7]=(H[7]+h)|0;
    }
    var hex = '';
    for (var i = 0; i < 8; i++) hex += ('00000000' + (H[i] >>> 0).toString(16)).slice(-8);
    return hex;
  }
  var _enc = (typeof TextEncoder !== 'undefined') ? new TextEncoder() : null;
  function utf8(str) {
    if (_enc) return _enc.encode(str);
    var out = []; for (var i = 0; i < str.length; i++) out.push(str.charCodeAt(i) & 0xff);
    return new Uint8Array(out);
  }
  var CRYPTO_SHIM = {
    createHash: function () {
      var data = '';
      return { update: function (s) { data += s; return this; }, digest: function () { return sha256bytes(utf8(data)); } };
    },
    randomBytes: function (n) {
      var arr = new Uint8Array(n);
      (self.crypto || window.crypto).getRandomValues(arr);
      var hex = ''; for (var i = 0; i < n; i++) hex += ('0' + arr[i].toString(16)).slice(-2);
      return { toString: function () { return hex; } };
    }
  };

  // ── Minimal CommonJS module system ──
  var registry = {}, cache = {};
  function define(id, factory) { registry[id] = factory; }
  function resolve(fromId, request) {
    if (request === 'crypto') return '__crypto__';
    if (request.charAt(0) === '.') {
      var base = fromId ? fromId.split('/').slice(0, -1).join('/') : '';
      var parts = (base + '/' + request).split('/');
      var out = [];
      for (var i = 0; i < parts.length; i++) {
        var p = parts[i];
        if (p === '' || p === '.') continue;
        if (p === '..') out.pop(); else out.push(p);
      }
      return out.join('/');
    }
    return request;
  }
  function req(fromId, request) {
    var id = resolve(fromId, request);
    if (id === '__crypto__') return CRYPTO_SHIM;
    if (cache[id]) return cache[id].exports;
    if (!registry[id]) throw new Error('Module not found: ' + request + ' from ' + fromId);
    var module = { exports: {} };
    cache[id] = module;
    registry[id](module, module.exports, function (r) { return req(id, r); });
    return module.exports;
  }
`;

const POSTLUDE_EXPORTS = `
  window.PAMRA_BACKEND = {
    markets: req(null, 'src/data/markets'),
    staff: req(null, 'src/data/staff'),
    amis: req(null, 'src/data/amisData'),
    mcmis: req(null, 'src/data/mcmisData'),
    news: req(null, 'src/data/newsData'),
    simulator: req(null, 'src/data/simulator'),
    gateSim: req(null, 'src/data/gateSimulator'),
    engine: req(null, 'src/engine/authenticityEngine'),
    ledger: req(null, 'src/engine/integrityLedger'),
    auth: req(null, 'src/auth')
  };
})();
`;

function buildModules() {
  return FILES.map((f) => {
    const src = fs.readFileSync(path.join(ROOT, f), 'utf8');
    const id = idOf(f);
    return `  define(${JSON.stringify(id)}, function (module, exports, require) {\n${src}\n  });\n`;
  }).join('\n');
}

const runtime = fs.readFileSync(path.join(ROOT, 'web', 'runtime.js'), 'utf8');

const output = PRELUDE + '\n' + buildModules() + POSTLUDE_EXPORTS + '\n' + runtime + '\n';

const outPath = path.join(ROOT, 'public', 'pamra-backend.js');
fs.writeFileSync(outPath, output);
console.log(`Built ${path.relative(ROOT, outPath)} (${(output.length / 1024).toFixed(1)} KB) from ${FILES.length} modules.`);
